// Normalize the inbound payload before fan-out.
// Mirrors flows/patient-lookup.py::_normalize_key — kept in sync by hand.
const body = ($json.body || $json) || {};
const phoneDigits = String(body.phone || '').replace(/\D+/g, '');
const email = String(body.email || '').trim().toLowerCase();
const name  = String(body.name  || '').trim();
let lookupKey = '';
if (phoneDigits) lookupKey = phoneDigits;
else if (email)  lookupKey = email;
else             lookupKey = name;

return [{ json: {
  payload: {
    name:  name  || null,
    phone: phoneDigits || null,
    email: email || null,
    dob:   body.dob || null,
    intent: body.intent || 'lookup',
  },
  lookupKey,
  hasKey: Boolean(lookupKey),
  sources: ['svigg','sis','drive'],
  actor: body.actor || 'n8n-flow:patient-lookup',
} }];

// Parse stdout of the CLI fallback into the same shape FastAPI returned.
const raw = ($json.stdout || '').trim();
if (!raw) {
  return [{ json: { ok: false, error: 'CLI returned empty stdout', stderr: $json.stderr || '' } }];
}
try {
  const parsed = JSON.parse(raw);
  return [{ json: parsed }];
} catch (e) {
  return [{ json: { ok: false, error: 'CLI stdout not JSON', detail: String(e), raw } }];
}

// Branch on decision.status -> existing / new / ambiguous / error.
const r = $json;
const status = (r && r.decision && r.decision.status) || 'error';
return [{ json: { ...r, _route: status } }];

// EXISTING patient: hand decision.merged_record downstream (Appointment / FileRequest flow).
return [{ json: {
  status: 'existing',
  patient: $json.decision.merged_record,
  source:  $json.decision.winning_source,
  confidence: $json.decision.confidence,
  audit_row_id: $json.audit_row_id || null,
} }];

// NEW patient: kick off intake flow (collect DOB, address, insurance).
return [{ json: {
  status: 'new',
  lookupKey: $('Normalize payload').first().json.lookupKey,
  next: 'intake-collect',
  audit_row_id: $json.audit_row_id || null,
} }];

// AMBIGUOUS: hand off to Q4 SMS approval gate so staff disambiguates.
return [{ json: {
  status: 'ambiguous',
  candidates: $json.decision.candidates || [],
  needs_staff_confirmation: true,
  audit_row_id: $json.audit_row_id || null,
} }];

// ERROR / dead-letter (Q10): write audit row + SMS on-call staff.
// The Python module already logged the failure; this node is the n8n-side
// escalation path. Wire to the dead-letter SMS workflow when it lands.
return [{ json: {
  status: 'error',
  sources: ($json.sources || []).map(s => ({ source: s.source, error: s.error })),
  session_expired: ($json.decision && $json.decision.session_expired) || [],
  needs_oncall_sms: true,
  audit_row_id: $json.audit_row_id || null,
} }];
